  ['https://registry.npmjs.org/@radix-ui/react-slot/-/react-slot-1.2.4.tgz', '.tmp-slot.tgz'],
  ['https://registry.npmjs.org/@radix-ui/react-compose-refs/-/react-compose-refs-1.1.2.tgz', '.tmp-crefs.tgz'],
];

for (const [url, file] of jobs) {
  const res = await fetch(url);
  writeFileSync(file, Buffer.from(await res.arrayBuffer()));
  console.log(file, res.status);
}

